-- 51 Night Bloom: one flower. The engine calls on_screen_entered /
-- on_screen_exited (its `visibility_notifier`); this opens or closes the
-- bloom and its light toward that, and tells the driver. Generated by
-- tools/gen_scenes.py.

local PALETTE = { { 1.0000, 0.1706, 0.5225 }, { 0.2633, 0.4480, 1.0000 }, { 1.0000, 0.6038, 0.1005 }, { 0.5225, 0.2140, 1.0000 }, { 0.2140, 1.0000, 0.6038 } }
local flowers = {}

function init(entity)
    local name = Entity.get_name(entity)
    local n = tonumber(string.sub(name, 7)) or 1
    flowers[entity] = {
        bloom = Entity.find_by_name(name .. "Bloom"),
        glow = Entity.find_by_name(name .. "Glow"),
        light = Entity.find_by_name(name .. "Light"),
        colour = PALETTE[((n - 1) % #PALETTE) + 1],
        open = false, k = 0, t = n * 0.7,
    }
end

function on_screen_entered(entity)
    local f = flowers[entity]
    if f then f.open = true end
    Event.send("bloom", entity, { d = 1 })
end

function on_screen_exited(entity)
    local f = flowers[entity]
    if f then f.open = false end
    Event.send("bloom", entity, { d = -1 })
end

function update(entity, dt)
    local f = flowers[entity]
    if not f or not f.bloom then return end
    local target = f.open and 1 or 0
    if f.k == target and not f.open then return end
    -- Opening is slow and closing quick, as a flower at dusk.
    local rate = f.open and 1.4 or 3.0
    f.k = f.k + (target - f.k) * math.min(1, dt * rate)
    if math.abs(f.k - target) < 0.002 then f.k = target end
    f.t = f.t + dt
    local breathe = 1 + 0.04 * math.sin(f.t * 1.7) * f.k
    local s = (0.15 + 0.85 * f.k) * breathe
    Transform.set_scale(f.bloom, s, s)
    local c = f.colour
    local glow = 0.3 + 2.4 * f.k
    Sprite.set_color(f.bloom, c[1] * glow, c[2] * glow, c[3] * glow, 1)
    if f.glow then Sprite.set_color(f.glow, c[1] * 1.5, c[2] * 1.5, c[3] * 1.5, 0.35 * f.k) end
    if f.light then Lighting.set_intensity(f.light, 1.6 * f.k * breathe) end
end
